const lockGmailBindingScope = `-- name: LockGmailBindingScope :one
SELECT w.id AS workspace_id, m.id AS member_id
FROM workspace w
JOIN member m
  ON m.workspace_id = w.id
 AND m.user_id = $1
WHERE w.id = $2
FOR KEY SHARE OF w, m
`

type LockGmailBindingScopeParams struct {
	UserID      pgtype.UUID `json:"user_id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

type LockGmailBindingScopeRow struct {
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	MemberID    pgtype.UUID `json:"member_id"`
}

// Gmail bindings deliberately have no database foreign keys. Pair this shared
// lock with LockWorkspaceForDelete's FOR UPDATE and LockMemberForRemoval's FOR
// UPDATE so a binding cannot commit after either parent cleanup has already
// swept its rows. Lock both parents before inserting or updating a binding.
func (q *Queries) LockGmailBindingScope(ctx context.Context, arg LockGmailBindingScopeParams) (LockGmailBindingScopeRow, error) {
	row := q.db.QueryRow(ctx, lockGmailBindingScope, arg.UserID, arg.WorkspaceID)
	var i LockGmailBindingScopeRow
	err := row.Scan(&i.WorkspaceID, &i.MemberID)
	return i, err
}

